// Mongolian texts of catalog.mjs: [English text, Mongolian text], in catalog order. The English side must match the T()
// text exactly (the build names any text without a translation and any entry whose English text changed or went away).
// Terms follow the app (src/Filee.App/Assets/i18n/mn.json): урьдчилсан тохиргоо (preset), хөдөлгүүр / нэмэлт хөдөлгүүр
// (engine, optional engine), цагираг самбар (donut toolbar), хянах хавтаснууд (watch folders), «Filee-ээр хөрвүүлэх»,
// Тохиргоо → Хөдөлгүүрүүд (Settings → Engines), preset names as in the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`, `видео ба аудио, хадмал гаргах болон HEIC хадгалах`],
  [`older office formats such as DOC, PPT and ODT`, `DOC, PPT, ODT зэрэг хуучин оффисын форматууд`],
  [`rare e-book formats and MOBI/AZW3 output`, `ховор цахим номын форматууд болон MOBI/AZW3 гаралт`],
  [`EPS and PostScript`, `EPS ба PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc болон бусад тэмдэглэгээ, Word → Markdown ба Markdown → слайд`],

  // Options
  [`quality`, `чанар`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `JPG, WEBP, AVIF-ийн чанарыг тохируулж болно: JPG анхдагчаар 90 %-иар хадгалагдах ба JPG 70 % урьдчилсан тохиргоо илүү жижиг файл гаргана.`],
  [`resize`, `хэмжээ өөрчлөх`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Хөрвүүлэх зуураа хувиар (жишээ нь хагас хэмжээ) эсвэл урт талын дээд хэмжээгээр хэмжээг өөрчилнө.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Зурагт бичигдэх DPI-г тохируулна, жишээ нь хэвлэхэд 300.`],
  [`grayscale`, `саарал өнгө`],
  [`A grayscale preset makes black-and-white copies.`,
    `Саарал өнгөтэй урьдчилсан тохиргоо хар цагаан хуулбар гаргана.`],
  [`metadata`, `мета өгөгдөл`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Мета өгөгдөл (EXIF, XMP, өнгөний профайл) анхдагчаар хадгалагдах ба хувийн нууцын үүднээс устгаж болно.`],
  [`ICO sizes`, `ICO хэмжээ`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `ICO файл анхдагчаар 256, 128, 64, 48, 32, 16 px хэмжээтэй зургийг агуулна; хэмжээг урьдчилсан тохиргоонд өөрчилж болно.`],
  [`TIFF compression`, `TIFF шахалт`],
  [`TIFF compression can be chosen (LZW by default).`, `TIFF шахалтыг сонгож болно (анхдагчаар LZW).`],
  [`white background`, `цагаан дэвсгэр`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG тунгалаг байдалгүй тул тунгалаг хэсгийг цагаанаар дүүргэнэ.`],
  [`merge into one PDF`, `нэг PDF болгож нэгтгэх`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Нэгтгэх урьдчилсан тохиргоо чирж тавьсан бүх файлыг нэг PDF болгоно.`],
  [`split pages`, `хуудас хуваах`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Хуваах урьдчилсан тохиргоо хуудас бүрийг дэд хавтсанд тусдаа PDF болгон хадгална.`],
  [`rotate & flip`, `эргүүлэх ба толин тусгал`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Эргүүлэх, толин тусгал хийх урьдчилсан тохиргоо зургийн өөрийн чиглэлийг харгалзсаны дараа зургийг зүүн, баруун эсвэл 180° эргүүлж, толин тусгал болгоно.`],
  [`Trace to SVG`, `SVG болгож мөшгөх`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Хоёр урьдчилсан тохиргоо зургийг вектор дүрс болгон мөшгөнө: SVG болгож мөшгөх нь 64 хүртэл өнгөөр, Зураасан зургийг SVG болгох нь лого, гарын үсэг, скан хийсэн зургийг хараар. Өөр програм хэрэггүй.`],
  [`remove background`, `арын дэвсгэр арилгах`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Арын дэвсгэр арилгах урьдчилсан тохиргоо жигд дэвсгэрийг тунгалаг болгоно: гарын үсэг, тамганы ард байгаа цаас, логоны дэвсгэр.`],
  [`page ranges`, `хуудасны муж`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `1-3,5 гэх мэт хуудасны муж хөрвүүлэлтийг хэрэгтэй хуудсаар хязгаарлана.`],
  [`render DPI`, `дүрслэх DPI`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Хуудсыг анхдагчаар 150 DPI-гаар дүрсэлнэ; хэвлэлийн чанарт 300 DPI-г сонгоно уу.`],
  [`one long image`, `нэг урт зураг`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Урт зураг урьдчилсан тохиргоо бүх хуудсыг нэг өндөр зураг болгон давхарлана, жишээ нь баримтыг бүхэлд нь нэг дор нийтлэхэд.`],
  [`compress PDF`, `PDF шахах`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `PDF шахах урьдчилсан тохиргоо PDF-ийг PDF хэвээр нь жижигрүүлнэ: зургуудыг 72, 150 эсвэл 300 dpi хүртэл багасгаж, гэрэл зургийг JPEG болгон дахин хадгалах ба текст, фонт, холбоос, хавчуурга, маягт хэвээр үлдэнэ. Жижигрүүлэх боломжгүй PDF өөрчлөгдөхгүй. Ghostscript суулгасан бол Filee түүгээр бас оролдож, жижиг гарсан үр дүнг хадгална.`],
  [`a picture per slide`, `слайд бүрт нэг зураг`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (слайд) хуудас бүрийн зургийг хуудасны хэмжээгээр тусдаа слайд дээр байрлуулж, хуудасны текстийг илтгэгчийн тэмдэглэлд хийнэ. Слайдууд PDF-тэй яг адил харагдах боловч засварлах боломжгүй; засварлах текст хэрэгтэй бол DOCX руу хөрвүүлнэ үү.`],
  [`vector PDF`, `вектор PDF`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `PDF вектор хэвээр үлдэх тул ямар ч томруулалтад болон хэвлэхэд тод харагдана.`],
  [`editable`, `засварлах боломжтой`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Үр дүн нь хуудасны зураг биш, засварлах боломжтой жинхэнэ текст ба догол мөртэй.`],
  [`attachments as ZIP`, `хавсралтыг ZIP болгох`],
  [`Attachments can be saved separately as one ZIP.`, `Хавсралтуудыг тусад нь нэг ZIP болгон хадгалж болно.`],
  [`one CSV per sheet`, `хуудас бүрт нэг CSV`],
  [`Workbooks with several sheets give one CSV per sheet.`, `Олон хуудастай ажлын номноос хуудас бүрт нэг CSV гарна.`],
  [`layout kept`, `хуудасны бүтэц хадгалагдана`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Хуудасны хэмжээ ба захын зай, хуудасны дугаартай толгой ба хөл, хүснэгт, текстийн хайрцаг, дүрс, зургийг хадгална.`],
  [`no Office needed`, `Office хэрэггүй`],
  [`No Microsoft Office or LibreOffice needed.`, `Microsoft Office эсвэл LibreOffice хэрэггүй.`],
  [`no Hancom Office needed`, `Hancom Office хэрэггүй`],
  [`No Hancom Office and no approval dialog.`, `Hancom Office болон зөвшөөрлийн цонх хэрэггүй.`],
  [`no AutoCAD needed`, `AutoCAD хэрэггүй`],
  [`No AutoCAD or DWG viewer needed.`, `AutoCAD эсвэл DWG үзэгч хэрэггүй.`],
  [`no re-encoding`, `дахин кодлохгүй`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Шинэ формат видео ба дууг байгаагаар нь агуулж чадвал (iPhone MOV → MP4) зөвхөн савыг нь солино: чанар алдагдахгүй, HDR хадгалагдаж, хэдхэн секундэд дуусна.`],
  [`720p option`, `720p сонголт`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `MP4 720p урьдчилсан тохиргоо том видеог хуваалцахад зориулж жижигрүүлнэ.`],
  [`extract audio`, `аудио гаргах`],
  [`Only the sound is saved, without the video track.`, `Видео замгүйгээр зөвхөн дууг хадгална.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `MP3 128k урьдчилсан тохиргоо илүү жижиг файл гаргах ба яриа бичлэгт тохиромжтой.`],
  [`extract`, `задлах`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Задлах урьдчилсан тохиргоо оронд нь архивыг хавтас руу задална.`],
  [`pack into one ZIP`, `нэг ZIP болгож багцлах`],
  [`Any selection of files can be packed into one ZIP.`, `Сонгосон ямар ч файлуудыг нэг ZIP болгон багцалж болно.`],
  [`DRM-free books`, `DRM-гүй ном`],
  [`Works with DRM-free books only.`, `Зөвхөн DRM-гүй номтой ажиллана.`],
  [`ALAC in M4A`, `M4A доторх ALAC`],
  [`M4A can hold lossless ALAC as well as AAC.`, `M4A нь AAC-ээс гадна алдагдалгүй ALAC-ийг агуулж чадна.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Видео урьдчилсан тохиргоо илүү жижиг файлд зориулж HEVC (H.265) эсвэл AV1-ээр кодлох ба 10 бит болон HDR видеог хадгална.`],
  [`hardware encoding`, `техник хангамжийн кодлол`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Видео урьдчилсан тохиргоонд Техник хангамжийн хурдасгуур ашиглахыг асааж H.264 ба HEVC-г график чип дээр (NVENC, Quick Sync, AMF, VideoToolbox эсвэл VA-API) кодлоорой: хамаагүй хурдан, бага эрчим хүч зарцуулах ба ижил чанартай үед арай том файл гарна. Анхдагчаар унтраалттай бөгөөд ашиглаж болох чип байхгүй бол видеог өмнөх шигээ кодлоно.`],
  [`every frame`, `бүх кадр`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Ихэвчлэн видеоноос нэг хөдөлгөөнгүй кадр гарна. Кадруудыг салгах урьдчилсан тохиргоо, эсвэл PNG ба JPG урьдчилсан тохиргоон дахь Видеоны кадр бүрийг хадгалах сонголт нь бүх кадрыг (эсвэл N дэх бүрийг) видеоны хажуудах хавтсанд зураг болгон хадгална.`],
  [`extract subtitles`, `хадмал гаргах`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Видео цагираг дээрх Хадмал салгах урьдчилсан тохиргоо видеоны эхний текст хадмалын замыг SRT болгон хадгална.`],
  [`saved as UTF-8`, `UTF-8-аар хадгалагдана`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Үр дүнг UTF-8-аар хадгална. CP949 (EUC-KR)-ээр хадгалсан солонгос файлыг танин зөв уншина.`],
  [`tables to CSV / Excel`, `хүснэгтийг CSV / Excel руу`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Хүснэгт хэлбэрийн өгөгдөл (бичлэгийн жагсаалт) мөн CSV ба Excel руу, тэдгээрээс хөрвөнө.`],
  [`picture preview`, `зургаар урьдчилан харах`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG эсвэл JPG нь загварыг урд баруун, дээрээс харсан сүүдэртэй зургийг гаргана.`],
  [`colours and textures`, `өнгө ба бүтэц`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Зорилтот формат агуулж чадвал өнгө, бүтэц, материалыг хадгална. STL зөвхөн хэлбэрийг хадгална.`],
  [`HDR tone-mapped`, `HDR тон тохируулга`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Windows-ийн JPEG XR-ээр хадгалдаг HDR дэлгэцийн зургийг тайрахын оронд ердийн гэрэлтэлт рүү тон тохируулна.`],
  [`Live Photo video`, `Live Photo видео`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Live Photo видеог салгах урьдчилсан тохиргоо iPhone Live Photo (iCloud-ын LIVP эсвэл MOV-тойгоо хамт гэрэл зураг) эсвэл Android Motion Photo-ийн видеог MP4 эсвэл MOV болгон хадгална. Эсрэгээр, Live Photo (iPhone) ба Motion Photo (Android) урьдчилсан тохиргоо видеоны богино хэсгийг хөдөлгөөнт гэрэл зураг болгоно; энэ нь одоохондоо туршилтын шатанд байна.`],
  [`WGS 84 longitude / latitude`, `WGS 84 уртраг / өргөрөг`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Үр дүн үргэлж уртраг, өргөрөгөөр (WGS 84) гарна. UTM, Web Mercator, Lambert эсвэл Albers-тэй Shapefile-ийг хөрвүүлэх тул зөв байрандаа нээгдэнэ; файлыг өөрийн формат руу нь хөрвүүлбэл дахин проекцлоно.`],
  [`save as ZIP`, `ZIP болгон хадгалах`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Shapefile нь таван файл (.shp, .shx, .dbf, .prj, .cpg) юм. Урьдчилсан тохиргоонд Үр дүнг ZIP болгон хадгалахыг, эсвэл тохиргоонд бүх газарзүйн үр дүнд үүнийг сонговол тэд нэг ZIP-д хамт явна.`],

  // Text that needs shaping
  [`DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX with text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) go to PDF and images through the optional LibreOffice engine`,
    `Хэлбэржүүлэлт шаардлагатай текст (араб, еврей, энэтхэг бичиг, тай болон бусад) агуулсан DOCX, TXT, Markdown, HTML, XLSX, PPTX, HWPX нь нэмэлт LibreOffice хөдөлгүүрээр PDF ба зураг руу хөрвөнө`],
  [`Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Хэлбэржүүлэлт шаардлагатай текст (араб, еврей, энэтхэг бичиг, тай болон бусад) нь үл хамаарах зүйл: ийм тексттэй DOCX, TXT, Markdown, HTML, XLSX, PPTX, HWPX файл нэмэлт LibreOffice хөдөлгүүрээр PDF ба зураг руу хөрвөнө. LibreOffice байхгүй бол эвдэрсэн PDF гаргахын оронд тухайн бичгийн нэрийг дурдсан мессежээр бүтэлгүйтнэ.`],

  // Camera RAW
  [`Canon CR2 RAW photo`, `Canon CR2 RAW гэрэл зураг`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 бол Canon-ы DSLR камеруудын олон жил хэрэглэсэн RAW гэрэл зургийн формат (шинэ Canon загварууд CR3 бичдэг). Боловсруулаагүй мэдрэгчийн өгөгдлийг хадгалдаг тул засварлах өргөн боломж үлдээнэ.`],
  [`Nikon NEF RAW photo`, `Nikon NEF RAW гэрэл зураг`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF бол Nikon-ы DSLR болон Z толингүй камеруудын RAW гэрэл зургийн формат. Бусад RAW файлын адил боловсруулаагүй мэдрэгчийн өгөгдлийг агуулах ба JPG-ээс хэд дахин том.`],

  // Images
  [`Images`, `Зураг`],
  [`images`, `зураг`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Гэрэл зураг ба график: iPhone HEIC ба Live Photo, Photoshop PSD, бүх томоохон брэндийн камерын RAW, хөдөлгөөнт APNG, DICOM, Windows-ийн HDR дэлгэцийн зураг (JPEG XR). Хөрвүүлэх зуураа хэмжээ өөрчлөх, эргүүлэх, чанар ба DPI тохируулах, мета өгөгдөл арилгах, эсвэл зургийг SVG болгон мөшгөх боломжтой.`],
  [`JPEG image`, `JPEG зураг`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG бол хамгийн өргөн хэрэглэгддэг гэрэл зургийн формат. Алдагдалтай шахалт нь файлыг жижиг байлгах боловч бага чанараар хадгалах бүрт зарим нарийн ширийн алдагдах ба тунгалаг байдалгүй.`],
  [`PNG image`, `PNG зураг`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG бол тунгалаг байдалтай алдагдалгүй зургийн формат бөгөөд дэлгэцийн зураг, лого, хурц ирмэгтэй графикт тохиромжтой. PNG-ээр хадгалсан гэрэл зураг ихэвчлэн JPG-ээс хамаагүй том байдаг.`],
  [`WebP image`, `WebP зураг`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP бол Google-ийн вэбэд зориулсан зургийн формат. Алдагдалтай ба алдагдалгүй шахалт, тунгалаг байдлыг дэмжих ба ихэвчлэн JPG, PNG-ээс жижиг боловч зарим засварлагч болон байршуулах маягт үүнийг одоо ч хүлээн авдаггүй.`],
  [`AVIF image`, `AVIF зураг`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF бол AV1 видео кодек дээр суурилсан орчин үеийн зургийн формат. JPG, WebP-ээс илүү сайн шахдаг ч хуучин програм хангамж, төхөөрөмжид дэмжлэг хязгаарлагдмал хэвээр байна.`],
  [`HEIC / HEIF image`, `HEIC / HEIF зураг`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) бол iPhone, iPad-ийн анхдагч гэрэл зургийн формат. Гэрэл зураг ихэвчлэн JPG-ийн тал орчим хэмжээтэй боловч Windows-ийн олон програм, вэб сайт, хуучин төхөөрөмж нээж чаддаггүй.`],
  [`GIF image / animation`, `GIF зураг / хөдөлгөөнт зураг`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF бол 256 өнгөөр хязгаарлагдсан, энгийн хөдөлгөөнийг дэмждэг хуучин зургийн формат. Чат, баримт бичиг, алдааны тайланд богино дуугүй давталт хуваалцах түгээмэл арга хэвээр байна.`],
  [`Windows icon`, `Windows дүрс тэмдэг`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO бол Windows-ийн дүрс тэмдгийн формат. Нэг ICO файл нэг зургийг хэд хэдэн хэмжээгээр (жишээ нь 16, 32, 48, 256 пиксел) агуулдаг тул ажлын самбараас вэб сайтын favicon хүртэл хаана ч тод харагдана.`],
  [`Photoshop document`, `Photoshop баримт`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD бол Adobe Photoshop-ын үндсэн формат. Давхарга, маск, тохируулгын тохиргоог хадгалдаг тул засварлахад тохиромжтой боловч ихэнх үзэгч болон вэб сайт нээж чаддаггүй.`],
  [`macOS icon`, `macOS дүрс тэмдэг`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS бол macOS-ийн дүрс тэмдгийн формат. ICO-гийн адил нэг зургийг хэд хэдэн хэмжээгээр, Retina дэлгэцэд 1024×1024 хүртэл багцалдаг бөгөөд Mac дээрх програмын дүрс тэмдэгт хэрэглэгдэнэ.`],
  [`Camera RAW`, `Камерын RAW`],
  [`Windows only`, `Зөвхөн Windows`],
  [`the photo of the Live Photo`, `Live Photo-гийн гэрэл зураг`],
  [`the video of the Live Photo`, `Live Photo-гийн видео`],

  // Vector graphics
  [`Vector graphics`, `Вектор график`],
  [`vector graphics`, `вектор график`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, Windows метафайл, Illustrator, EPS/PostScript болон CorelDRAW, Visio, LibreOffice Draw-ийн зураг. SVG нь CAD-д зориулж DXF эсвэл DWG болж бас хөрвөнө.`],
  [`SVG vector graphic`, `SVG вектор график`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG бол XML дээр суурилсан вектор графикийн формат. Дүрс ба текст ямар ч хэмжээнд тод хэвээр байх тул вэб дэх лого, дүрс тэмдэгт тохиромжтой боловч олон програм ба байршуулах маягт зөвхөн пикселийн зураг хүлээн авдаг.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS бол хэвлэл, дизайны ажлаас гаралтай вектор формат бөгөөд хэвлэх үйлдвэрт илгээх лого, чимэглэлд ихэвчлэн хэрэглэдэг. Орчин үеийн ихэнх програм PostScript орчуулагчгүйгээр үүнийг харуулж чаддаггүй.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `PDF агуулгатайгаар хадгалсан AI файл (Illustrator-ын анхдагч)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `PDF-ийг зураг, засварлах боломжтой Word эсвэл HWPX баримт, PowerPoint слайд, текст эсвэл комиксын архив болгох, мөн нэгтгэх, хуваах, шахах эсвэл хуудас сонгох.`],
  [`PDF document`, `PDF баримт`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF бол хаана ч адилхан харагдах ёстой баримт хуваалцах стандарт. Фонт, бүтэц, зураг тогтмол бөгөөд ямар ч төхөөрөмж дээр нээгдэнэ. Энэ нь бас PDF-ийг засварлахад хэцүү болгодог.`],
  [`one page`, `нэг хуудас`],

  // Documents
  [`Documents`, `Баримт бичиг`],
  [`documents`, `баримт бичиг`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Microsoft Office-гүйгээр Word баримт, Хятадын OFD цахим нэхэмжлэх, нэмэлт LibreOffice хөдөлгүүрээр хуучин болон ховор текст боловсруулагчийн форматууд, хадгалсан цахим шуудан (EML ба Outlook MSG).`],
  [`Word document`, `Word баримт`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX бол Word 2007-оос хойших Microsoft Word-ийн формат (Office Open XML). Тайлан, захидал, маягт зэрэг засварлах боломжтой баримтын хамгийн түгээмэл формат.`],
  [`Word 97–2003 document`, `Word 97–2003 баримт`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC бол Word 97–2003-ийн хоёртын формат. Хуучин архив, албан ёсны маягт, хуучин системүүд одоо ч гаргадаг боловч DOCX-ээр солигдож байна.`],
  [`E-mail message`, `Цахим шуудангийн мессеж`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML бол толгой мэдээлэл, мессеж, хавсралттайгаа файл болгон хадгалсан нэг цахим шуудан (MIME формат). Outlook, Thunderbird зэрэг ихэнх шуудангийн програм нээж чадна.`],
  [`Outlook message`, `Outlook мессеж`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG бол Microsoft Outlook-оос цахим шууданг чирж гаргахад хадгалагддаг файл. Зөвхөн Outlook нээдэг тул Outlook-гүй PC эсвэл утсан дээр уншихад хэцүү.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `Солонгос HWP/HWPX`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Hancom Office-гүйгээр солонгос Hancom Hangul баримт: HWP ↔ HWPX, PDF, зураг, Word, текст, Markdown, HTML руу, мөн Word, Excel, PowerPoint, Markdown, PDF-ээс HWPX.`],
  [`Hangul document (HWP)`, `Hangul баримт (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP бол Солонгосын төрийн байгууллага, сургууль болон олон компанийн стандарт текст боловсруулагч Hancom Office Hangul (한글)-ийн баримтын формат. Солонгосоос гадна үүнийг нээж чадах програм цөөхөн.`],
  [`Hangul document (HWPX)`, `Hangul баримт (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX бол Hancom Hangul-ийн нээлттэй, XML дээр суурилсан формат (OWPML, Солонгосын үндэсний стандарт KS X 6101). Солонгосын төрийн байгууллагууд хоёртын HWP форматаас үүн рүү шилжиж байна.`],

  // Spreadsheets
  [`Spreadsheets`, `Хүснэгт`],
  [`spreadsheets`, `хүснэгт`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Excel-гүйгээр Excel, OpenDocument болон CSV/TSV хүснэгтийг Excel-тэй адил хуудсанд багтааж PDF руу эсвэл хоорондоо хөрвүүлнэ.`],
  [`Excel workbook`, `Excel ажлын ном`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX бол Excel 2007-оос хойших Microsoft Excel-ийн ажлын номын формат. Нэг ажлын ном томьёо, хэлбэржүүлэлт, диаграм, зурагтай хэд хэдэн хуудас агуулж чадна.`],
  [`Excel 97–2003 workbook`, `Excel 97–2003 ажлын ном`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS бол Excel 97–2003-ийн хоёртын ажлын номын формат. Олон хуучин систем, банк ба нягтлан бодох бүртгэлийн экспорт одоо ч гаргадаг.`],
  [`Comma-separated values`, `Таслалаар тусгаарласан утга`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV бол мөр бүрт хүснэгтийн нэг мөр бүхий энгийн текст. Бүх хүснэгтийн програм, өгөгдлийн сан, програмчлалын хэл уншдаг боловч хэлбэржүүлэлт, томьёо, олон хуудасгүй.`],

  // Presentations
  [`Presentations`, `Илтгэл`],
  [`presentations`, `илтгэл`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint-гүйгээр PowerPoint-ийг PDF, зураг, HWPX руу; хуучин PPT, ODP, Keynote-ийг нэмэлт LibreOffice хөдөлгүүрээр.`],
  [`PowerPoint presentation`, `PowerPoint илтгэл`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX бол PowerPoint 2007-оос хойших Microsoft PowerPoint-ийн формат. Текст, зураг, дүрс, хүснэгт, тэмдэглэл, хөдөлгөөнт эффекттэй слайдуудыг агуулна.`],
  [`PowerPoint 97–2003 presentation`, `PowerPoint 97–2003 илтгэл`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT бол PowerPoint 97–2003-ийн хоёртын формат. Хуучин лекцийн слайд, архивласан илтгэл ихэвчлэн PPT хэвээр байдаг.`],

  // Text & markup
  [`Text & markup`, `Текст ба тэмдэглэгээ`],
  [`text and markup`, `текст ба тэмдэглэгээ`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Энгийн текст, Markdown, HTML болон хадгалсан вэб хуудсыг (MHTML) PDF, Word, HWPX, EPUB руу. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter болон бусад тэмдэглэгээ нэмэлт Pandoc хөдөлгүүрийг ашиглах ба тэр нь Markdown-ыг PowerPoint слайд болгож бас чадна.`],
  [`Plain text`, `Энгийн текст`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT бол ямар ч хэлбэржүүлэлтгүй энгийн текст бөгөөд хамгийн энгийн, хаана ч ажилладаг баримтын формат. Ялгаатай байж болох цорын ганц зүйл бол тэмдэгтийн кодчилол (UTF-8, UTF-16 эсвэл хуучин кодын хуудас).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown бол хөнгөн энгийн текстэн тэмдэглэгээ: гарчигт #, жагсаалтад *, тод бичигт **. Тэмдэглэл, README файл, баримтжуулалтад түгээмэл бөгөөд дүрслэхгүйгээр ч уншигдахуйц.`],
  [`Web page (HTML)`, `Вэб хуудас (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML бол вэб хуудасны хэл. Хадгалсан .html файл ямар ч хөтөч дээр нээгдэх боловч харагдах байдал нь хөтөч болон холбосон загвар, зургаас хамаарах ба офлайн үед тэдгээр байхгүй байж болно.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `LOG файл болон скриптийг (PY, PAC, BAT, COMMAND) текст болгон уншдаг бөгөөд хэзээ ч ажиллуулдаггүй`],
  [`the saved page, with its pictures`, `хадгалсан хуудас, зурагтайгаа`],

  // Data
  [`Data`, `Өгөгдөл`],
  [`data files`, `өгөгдлийн файл`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML, XML-ийг хооронд нь, мөн хүснэгтийг CSV ба Excel руу болон тэдгээрээс. vCard харилцагчдыг CSV руу, CSV-ээс, хуучин утаснаас ч. Юу ч суулгах шаардлагагүй.`],
  [`JSON data`, `JSON өгөгдөл`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON бол вэбийн өгөгдлийн формат: объект, жагсаалт, текст, тоог энгийн текстээр. API, програм, тохиргооны файлууд хаа сайгүй ашигладаг.`],
  [`YAML data`, `YAML өгөгдөл`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML нь JSON-той ижил төрлийн өгөгдлийг хаалтын оронд доголоор бичиж хадгална. Docker, Kubernetes, CI дамжуулах хоолой болон олон програмын тохиргооны файл YAML байдаг.`],
  [`vCard contacts`, `vCard харилцагчид`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) бол харилцагчдын стандарт файл. Утас, Outlook, Google Contacts, iCloud хаягийн дэвтрийг vCard болгон, ихэвчлэн олон харилцагчийг нэг файлд экспортолдог.`],

  // E-books & comics
  [`E-books & comics`, `Цахим ном ба комикс`],
  [`e-books and comics`, `цахим ном ба комикс`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook болон комиксын архивыг (CBZ, CBR, CB7…) PDF, EPUB, Word гэх мэт рүү, мөн Kobo уншигчид зориулсан KEPUB руу. Зөвхөн DRM-гүй ном.`],
  [`EPUB e-book`, `EPUB цахим ном`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB бол цахим номын нээлттэй стандарт. Текст ямар ч дэлгэцэнд тааруулан дахин байрших ба ихэнх цахим ном уншигч, унших програм дэмждэг; Kindle EPUB-ийг Send to Kindle-ээр хүлээн авдаг.`],
  [`Kindle / Mobipocket e-book`, `Kindle / Mobipocket цахим ном`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI бол Amazon Kindle олон жил хэрэглэсэн хуучин Mobipocket цахим номын формат. Хуучин цахим номын цуглуулгад одоо ч түгээмэл боловч Amazon AZW3/KFX болон EPUB руу шилжсэн.`],

  // Video
  [`Video`, `Видео`],
  [`video`, `видео`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Бүх түгээмэл видео форматыг MP4 (H.264, HEVC эсвэл AV1), WebM, MOV, MKV, AVI, GIF эсвэл APNG руу, 720p сонголттой, график чип дээрх техник хангамжийн кодлолтой, аудиог MP3 эсвэл M4A болгон гаргаж, бүх кадрыг зураг болгон хадгална. Нэмэлт FFmpeg хөдөлгүүрийг ашиглана.`],
  [`MPEG-4 video`, `MPEG-4 видео`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) бол хамгийн нийцтэй видео формат. Утас, зурагт, хөтөч, бүх видео сайт дээр тоглогдох ба ихэвчлэн H.264 эсвэл H.265 видео, AAC аудиотой.`],
  [`QuickTime movie`, `QuickTime кино`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV бол iPhone ба Mac-ийн хэрэглэдэг Apple-ийн QuickTime видео формат. Ихэвчлэн H.264 эсвэл HEVC видео агуулдаг боловч зарим засварлагч, зурагт, вэб сайт MP4-ийг илүү сайн боловсруулдаг.`],
  [`Matroska video`, `Matroska видео`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) бол олон видео, аудио, хадмалын зам агуулж чадах уян хатан нээлттэй сав. Кино, бичлэгт түгээмэл боловч утас, зурагт, засварлагч үүнийг үргэлж тоглуулж чаддаггүй.`],
  [`WebM video`, `WebM видео`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM бол хөтөчид зориулсан нээлттэй видео формат (VP8/VP9 эсвэл AV1 видео, Vorbis эсвэл Opus аудиотой). Дэлгэцийн бичлэг ба татаж авсан файл ихэвчлэн WebM байдаг ч олон засварлагч, төхөөрөмж MP4 хүлээдэг.`],
  [`AVI video`, `AVI видео`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI бол 1990-ээд оны Microsoft-ын видео сав. Видео камер, хуучин камер, архивт одоо ч AVI файл байдаг бөгөөд тэдгээр нь ихэвчлэн том, утсан дээр муу дэмжигддэг.`],
  [`one still frame or every frame`, `нэг хөдөлгөөнгүй кадр эсвэл бүх кадр`],

  // Audio
  [`Audio`, `Аудио`],
  [`audio`, `аудио`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Хөгжим, бичлэг, дуу хоолойн тэмдэглэлийг MP3, M4A, WAV, FLAC, OGG, Opus, AAC эсвэл алдагдалгүй WavPack, TTA руу. APE, DSD, DTS-ийг бас уншина. Нэмэлт FFmpeg хөдөлгүүрийг ашиглана.`],
  [`MP3 audio`, `MP3 аудио`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 бол сонгодог шахсан аудио формат. Бараг бүх тоглуулагч, машины аудио, утас тоглуулдаг тул хөгжим, подкаст, бичлэг хуваалцахад хамгийн найдвартай сонголт.`],
  [`MPEG-4 audio`, `MPEG-4 аудио`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A бол iTunes, iPhone-ийн дуу хоолойн тэмдэглэл болон олон дуу хураагуурын хэрэглэдэг, ихэвчлэн AAC бүхий MPEG-4 аудио файл. Жижиг хэмжээтэй ч сайн сонсогддог боловч зарим тоглуулагч, машины аудио зөвхөн MP3 хүлээн авдаг.`],
  [`WAV audio`, `WAV аудио`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV бол бичлэг, засварт хэрэглэдэг шахаагүй аудио (ихэвчлэн PCM). Эх сурвалжтай яг адил сонсогдох боловч CD чанараар минут тутамд 10 MB орчим эзэлнэ.`],
  [`FLAC lossless audio`, `FLAC алдагдалгүй аудио`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC бол алдагдалгүй шахсан аудио: чанарыг огт алдахгүйгээр файлыг WAV-ийн тал орчим болгож багасгадаг тул хөгжмийн сан болон өндөр нягтралтай татаж авалтын хамгийн дуртай формат.`],

  // Subtitles
  [`Subtitles`, `Хадмал`],
  [`subtitles`, `хадмал`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML, MicroDVD-г ямар ч хөдөлгүүргүйгээр хооронд нь хөрвүүлж UTF-8-аар хадгална; SSA ба SCC-г уншина. CP949-тэй солонгос SMI ба SRT файлыг зөв уншина. Видео доторх хадмалыг FFmpeg-ээр гаргана.`],
  [`SubRip subtitles`, `SubRip хадмал`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) бол хамгийн түгээмэл хадмалын файл: эхлэх, дуусах цагтай дугаарласан хэсгүүд ба энгийн текст. Бараг бүх тоглуулагч, засварлагч, видео сайт хүлээн авдаг.`],
  [`Advanced SubStation Alpha subtitles`, `Advanced SubStation Alpha хадмал`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) бол анимэ сонирхогчдын орчуулга болон Aegisub-ийн фонт, өнгө, байрлал, эффекттэй загварлаг хадмалын формат. Олон төхөөрөмж, сайт зөвхөн энгийн SRT хүлээн авдаг.`],
  [`WebVTT subtitles`, `WebVTT хадмал`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) бол HTML5 видеоны хадмалын формат. Вэб тоглуулагч, YouTube, онлайн сургалтын платформууд ашигладаг.`],
  [`SAMI subtitles (SMI)`, `SAMI хадмал (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) бол Microsoft-ын HTML-тэй төстэй хадмалын формат. Солонгост одоо ч сонгодог хадмалын файл хэвээр бөгөөд ихэвчлэн хуучин CP949 кодчилолоор хадгалагдсан байдаг тул шинэ тоглуулагчид эвдэрсэн текст харуулдаг.`],

  // Archives
  [`Archives`, `Архив`],
  [`archives`, `архив`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `ZIP, 7Z, RAR, TAR, дискний дүрс болон бусад олон архивын форматыг дагалдах 7-Zip хөдөлгүүрээр дахин багцлах эсвэл задлах, эсвэл ямар ч файлыг нэг ZIP болгон багцлах.`],
  [`ZIP archive`, `ZIP архив`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP бол бүх нийтийн архивын формат. Windows, macOS, утас болон бараг бүх байршуулах маягт нэмэлт програмгүйгээр нээдэг.`],
  [`7-Zip archive`, `7-Zip архив`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z бол 7-Zip-ийн нээлттэй архивын формат. LZMA2 шахалт нь ихэвчлэн ZIP-ээс жижиг файл гаргадаг ч бүх систем, вэб сайт нээж чаддаггүй.`],
  [`RAR archive`, `RAR архив`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR бол хэсэг хэсгээр хуваасан татаж авалтад түгээмэл WinRAR-ийн өмчийн архивын формат. Windows 11-ийн сүүлийн хувилбарууд RAR-ийг нээж чадах ч үүсгэж чаддаггүй бөгөөд олон хэрэгсэл зөвхөн ZIP хүлээн авдаг.`],
  [`Any files`, `Ямар ч файл`],

  // CAD drawings
  [`CAD drawings`, `CAD зураг`],
  [`CAD drawings [in running text]`, `CAD зураг`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `AutoCAD DWG ба DXF: AutoCAD-гүйгээр хооронд нь эсвэл PDF, SVG, PNG руу хөрвүүлнэ.`],
  [`AutoCAD drawing`, `AutoCAD зураг`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG бол AutoCAD-ийн үндсэн зургийн формат бөгөөд архитектур, инженерчлэлийн хамгийн түгээмэл CAD файл. AutoCAD эсвэл DWG үзэгчгүйгээр нээх, хуваалцахад хэцүү.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) бол CAD зургийн Autodesk-ийн солилцооны формат. Лазер огтлогч, CNC програм болон ихэнх CAD програм уншдаг тул хэрэгслүүдийн хооронд зураг шилжүүлэх ердийн арга.`],

  // 3D models
  [`3D models`, `3D загвар`],
  [`3D models [in running text]`, `3D загвар`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF, PLY-г хооронд нь, мөн FBX-ийг тэдгээрийн аль нь ч руу, формат нь хадгалж чадвал өнгө, бүтэц, материалтай нь, мөн сүүдэртэй PNG эсвэл JPG зураг руу хөрвүүлнэ. Юу ч суулгах шаардлагагүй.`],
  [`glTF binary (GLB)`, `glTF хоёртын (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB бол вэб, AR, тоглоомын хөдөлгүүрийн 3D формат glTF-ийн нэг файлт хувилбар. Тор, материал, бүтцийг нэг авсаархан файлд багцалдаг.`],
  [`STL 3D model`, `STL 3D загвар`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL бол 3D хэвлэлийн сонгодог файл. Хэлбэрийн зөвхөн гурвалжнуудыг өнгө, нэгжгүйгээр хадгалах ба бүх slicer болон CAD програм уншдаг.`],
  [`Wavefront OBJ model`, `Wavefront OBJ загвар`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) бол бараг бүх 3D програм нээдэг энгийн текстэн 3D формат. Материал, бүтэц нь хажууд нь .mtl файл болон зургууд байдлаар байна.`],

  // Fonts
  [`Fonts`, `Фонт`],
  [`fonts`, `фонт`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Ширээний болон вэб фонт: TTF, OTF, WOFF, WOFF2, EOT-ийг хооронд нь.`],
  [`TrueType font`, `TrueType фонт`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) бол Windows ба macOS дээрх хамгийн түгээмэл ширээний фонтын формат. Фонтыг ямар ч програмд ашиглахын тулд суулгана.`],
  [`OpenType font`, `OpenType фонт`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) бол Adobe ба Microsoft-ын фонтын формат. PostScript (CFF) контуртай OpenType фонт мэргэжлийн үсгийн хэлбэрт түгээмэл бөгөөд лигатур зэрэг боломжуудыг дэмждэг.`],
  [`Web font (WOFF2)`, `Вэб фонт (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 бол бүх орчин үеийн хөтчийн дэмждэг шахсан вэб фонтын формат. Ихэвчлэн WOFF-оос 30 % орчим жижиг тул хуудас хурдан ачаалагдана.`],

  // Geospatial data
  [`Geospatial data`, `Газарзүйн өгөгдөл`],
  [`geospatial data`, `газарзүйн өгөгдөл`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Газрын зураг ба GPS өгөгдөл: GeoJSON, KML, KMZ, GPX, Shapefile-ийг хооронд нь болон CSV, Excel, JSON руу, мөн координаттай CSV-г буцааж газрын зургийн файл болгоно. Зөвхөн вектор өгөгдөл (цэг, шугам, талбай), үргэлж уртраг, өргөрөгөөр хадгална. Юу ч суулгах шаардлагагүй.`],
  [`one row per feature, with its coordinates`, `объект бүрт нэг мөр, координаттайгаа`],
  [`a CSV with longitude and latitude columns or WKT`, `уртраг, өргөрөгийн баганатай эсвэл WKT бүхий CSV`],

  // Camera RAW group (conversion pages)
  [`Camera RAW photo`, `Камерын RAW гэрэл зураг`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Камерын RAW файл (CR2, CR3, NEF, ARW, DNG, RAF, ORF гэх мэт) гэрэл зургийн боловсруулаагүй мэдрэгчийн өгөгдлийг агуулна. Засварлахад хамгийн их нарийн ширийнийг хадгалдаг ч том бөгөөд харахад тусгай програм хэрэгтэй.`],

  // Conversion guides: images
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `Вэб сайт, хуучин Windows програм эсвэл iPhone-гүй хүнд таны гэрэл зураг хэрэгтэй үед JPG бол найдвартай сонголт. Олон HEIC гэрэл зургийг нэг дор хөрвүүлж, JPG бүрийг эхийнх нь хажууд хадгална.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Гэрэл зургаа JPG шахалт нэмэлгүйгээр үргэлжлүүлэн засварлах бол PNG-г сонгоорой. PNG алдагдалгүй тул эх HEIC-ээс хэд дахин том файл гарна гэж тооцоорой.`],
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC нь iPhone-ийн хадгалдаг шиг ижил чанартай JPG-ийн тал орчим зайд гэрэл зургийг хадгална. HEIC хадгалахад үнэгүй FFmpeg хөдөлгүүр (100 MB орчим, програм дотор нэг удаа татна) хэрэгтэй. EXIF, өнгөний профайл, чиглэлийг хадгална.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Вэб сайтаас хадгалсан зураг ихэвчлэн WebP байдаг. PNG руу хөрвүүлбэл бүрэн чанар ба тунгалаг байдал хадгалагдах тул үр дүн ямар ч засварлагч, слайд, баримтад ажиллана.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Зураг нь гэрэл зураг бөгөөд файлын хэмжээ чухал үед JPG-г сонгоорой, жишээ нь WebP хүлээн авдаггүй байршуулах маягтад.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `PNG-ээр хадгалсан дэлгэцийн зураг, экспортолсон гэрэл зураг олон мегабайт байж болно. Гэрэл зураг JPG болоход ихэвчлэн хамаагүй жижгэрдэг; текст ихтэй дэлгэцийн зураг ба логод PNG ихэвчлэн илүү тохиромжтой хэвээр байна.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `JPG-ийг PNG руу хөрвүүлэх нь JPG шахалтаар алдагдсан нарийн ширийнийг сэргээхгүй ч цаашдын алдагдлыг зогсооно: дараагийн бүх засвар, хадгалалт алдагдалгүй байна. Зургийг засварлах эсвэл засварлагчид тунгалаг байдал нэмэхээс өмнө хөрвүүлээрэй.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Орчин үеийн вэб сайт, утаснаас ирсэн AVIF зураг олон хуучин програм, зураг үзэгч, байршуулах маягтад нээгддэггүй. JPG хаана ч нээгдэх ба үүний оронд файл арай том болно.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP вэб сайтад тохиромжтой: гэрэл зураг JPG-ээс хамаагүй жижиг болж, график тунгалаг байдлаа хадгална. WEBP урьдчилсан тохиргоо 85 чанараар хадгалдаг нь вэбэд сайн тэнцвэр юм.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Скан хийсэн хуудас, баримт, баримт бичгийн гэрэл зургийг ихэвчлэн нэг PDF болгож илгээх шаардлагатай байдаг. Зургуудыг нэгтгэх урьдчилсан тохиргоон дээр тавьж нэг PDF авах, эсвэл PDF дээр тавьж зураг бүрт нэг PDF авна. Анхдагчаар хуудас бүр зургийнхаа хэмжээг авна.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Нэг ICO нь ширээний компьютер, Explorer, ажлын самбарын дүрс тэмдэгт Windows-д хэрэгтэй бүхнийг хамардаг бөгөөд вэб сайтын favicon болж бас ажиллана. Хамгийн тод үр дүнд хүрэхийн тулд хамгийн багадаа 256×256 px хэмжээтэй дөрвөлжин PNG-ээс эхлээрэй.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Windows дээр Mac програмын дүрс тэмдэг хийхэд ихэвчлэн нэмэлт хэрэгсэл шаардлагатай; Filee PNG-г шууд ICNS файл болгоно. Retina хэмжээнүүд тод хэвээр байхын тулд 1024×1024 px дөрвөлжин PNG ашиглаарай.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Photoshop-гүй хүмүүстэй Photoshop дизайнаа хуваалцаарай: PNG нь харагдах давхаргуудыг нэгтгэж, тунгалаг байдлыг хадгалан зургийг хадгалсан хэвээр нь харуулна. PNG давхарга хадгалж чаддаггүй тул засварлахдаа PSD-г хадгалаарай.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee нь Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One болон бусад брэндийн RAW файлыг уншиж, анхдагч тохиргоогоор боловсруулна. Зураг авалтаас хуваалцахад бэлэн JPG авах хурдан арга; бүтээлч засварт эхлээд RAW засварлагч ашиглаарай.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Санах ойн картан дахь бүх CR2 файлаа нэг дор чирж тавиарай: Filee тэдгээрийг зэрэгцээ хөрвүүлж, JPG бүрийг RAW файлынх нь хажууд хадгална. Шинэ Canon камерууд CR3 бичдэг бөгөөд Filee үүнийг бас уншина.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `NEF файл байгаагаар нь илгээхэд хэт том, хэт ер бусын. JPG болохоор жижиг, хаана ч харагдах гэрэл зураг болно; мессежийн програмд JPG 70 % эсвэл хагас хэмжээний урьдчилсан тохиргоо ашиглаарай. Coolpix камерын Nikon NRW файл ч адилхан ажиллана.`],

  // Conversion guides: vector
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Олон програм, слайд, байршуулах маягт SVG хүлээн авдаггүй. Filee вектор зургийг тунгалаг байдалтай PNG болгон дүрсэлнэ; шахсан SVGZ файл ч ажиллана.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG-ээс PDF вектор хэвээр үлдэнэ: шугам, текст ямар ч томруулалтад болон хэвлэхэд тод хэвээр байж, файл жижиг байна. Лого, диаграмыг хэвлэх үйлдвэрт илгээх эсвэл баримтад оруулахад тохиромжтой.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS-ийг зөвхөн PostScript орчуулагч харуулж чадна; Filee үүнд Ghostscript ашигладаг. PDF вектор зургийг хадгалах тул хаана ч нээгдэж, тод хэвлэгдсээр байна. PostScript (.ps) файл ч адилхан ажиллана.`],

  // Conversion guides: PDF
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Хуудас бүр тусдаа JPG болох тул 10 хуудастай PDF-ээс 10 зураг гарна. PDF биш, зураг хүлээн авдаг чат, слайд, сошиал нийтлэлд тохиромжтой.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG нь JPG-ийн гажиггүйгээр текст, шугамыг тод хадгалдаг тул слайд, диаграм, нотны хуудас болон тэмдэглэгээ хийх эсвэл илтгэлд оруулах хуудсанд тохирно.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee PDF-ийг хуудасны зургийн оронд жинхэнэ догол мөртэй Word баримт болгох тул үсгийн алдаа засах эсвэл текстийг дахин ашиглах боломжтой. Нарийн бүтэцтэй хуудсыг бага зэрэг засах шаардлагатай байж болох ба зөвхөн хуудасны зураг агуулсан скан PDF-ээс гаргах текст байхгүй.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee өөрөө PDF → Word → EPUB дарааллаар явдаг тул текст утас эсвэл цахим ном уншигчийн дэлгэцэнд тааруулан дахин байршина. Жинхэнэ тексттэй PDF-д хамгийн сайн ажиллана. Гарчиг энгийн догол мөр болж гарах ба скан хуудсанд хөрвүүлэх текст байхгүй.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee PDF-ийн текстийг Word баримт руу авч, HWPX болгон бичээд дараа нь HWP болгон хадгална, бүгдийг дотоод хөдөлгүүрээр. Жинхэнэ тексттэй PDF-д ажиллана. Нарийн бүтэцтэй хуудсыг бага зэрэг засах шаардлагатай байж болох ба скан хуудаснаас гаргах текст байхгүй.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee PDF-ийг эхлээд Word баримт, дараа нь Markdown болгож, ялгаж чадах газраа догол мөр, гарчиг, тод бичгийг хадгална. Тэмдэглэл, вики эсвэл текстийг өөр хэрэгсэлд буулгахад хэрэгтэй. Скан хуудсанд хөрвүүлэх текст байхгүй.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Солонгосын албан газрууд ихэвчлэн Hangul форматтай баримт шаарддаг. Filee PDF-ийн текстийг Hancom Hangul-д нээж засварлах боломжтой HWPX файл болгон хөрвүүлэх ба хөрвүүлэхэд Hancom Office хэрэггүй; маягт хуучин форматыг шаардвал дараа нь HWP болгоорой.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `PDF-ийг PowerPoint-д харуулах эсвэл байгаа слайдад нэмэх шаардлагатай үед тохиромжтой: хуудас бүр PDF-тэй яг адил харагдах слайд болж, хуудасны текст илтгэгчийн тэмдэглэлд хүлээж байна. Слайдууд зураг тул үг хэллэгийг өөрчлөх бол PDF-ийг DOCX руу хөрвүүлээрэй.`],

  // Conversion guides: documents
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Microsoft Word эсвэл LibreOffice хэрэггүй: Filee DOCX-ийг өөрөө уншиж, толгой, хөл, хүснэгт, зурагтай хуудсыг байрлуулна. Хэд хэдэн баримтыг нэгтгэх урьдчилсан тохиргоон дээр тавьж нэг PDF болгоорой.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Архив, албан ёсны маягт, хуучин системээс ирсэн Word 97–2003 баримт хаана ч нээгдэх PDF болно. Ижил хөдөлгүүр ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord, Apple Pages файлыг бас хөрвүүлнэ.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Бүртгэл, нэхэмжлэх, хуулийн баримтад зориулж цахим шууданг PDF болгон хадгалаарай: PDF илгээгч, хүлээн авагч, огноо, гарчиг, мессежийг харуулах ба шуудангийн програмгүйгээр хаана ч нээгдэнэ.`],

  // Conversion guides: HWP
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee HWP хуудсыг нээлттэй эхийн Hangul хөдөлгүүр rhwp-ээр дүрсэлдэг тул Hancom Office ч, түүний зөвшөөрлийн цонх ч оролцохгүй. HWP нээж чаддаггүй хүмүүст солонгос баримт илгээхэд хэрэгтэй.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Hangul баримтыг гадаад дахь хамт олны засварлаж чадах Word файл болгоорой. Текст, догол мөр, хүснэгт шилжинэ; олон хөвөгч объекттой бүтцийг Word-д хурдан шалгах нь зүйтэй.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `Hangul-ийн XML дээр суурилсан шинэ формат HWPX нь HWP-тэй адил хөрвөнө: дотоод rhwp хөдөлгүүр хуудсыг бүрэн офлайнаар байрлуулна. Төрийн байгууллагын HWPX маягтыг PDF болгон архивлахад тохиромжтой.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Зарим систем болон шинэ ажлын урсгал зөвхөн HWPX хүлээн авдаг. Filee хоёртын HWP-г Hancom Office-гүйгээр rhwp-ээр HWPX болгох ба олон хуучин баримтыг нэг дор хөрвүүлнэ.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Hangul-ийн хуучин хувилбарууд болон зарим илгээх портал одоо ч .hwp хүлээдэг. Filee HWPX-ийг rhwp-ээр буцааж HWP болгодог тул файл бүрийг Hangul-д нээж дахин хадгалах шаардлагагүй.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Filee-ийн өөрийн HWPX бичигч Word-ийн бүтцийг шилжүүлнэ: хуудасны хэмжээ ба захын зай, хуудасны дугаартай толгой ба хөл, нэгтгэсэн нүдтэй хүснэгт, хүрээ ба сүүдэр, текстийн хайрцаг, дүрс, зураг. Бичсэн файл бүрийг тестэд HWPX-ийн гурван бие даасан уншигчаар шалгадаг.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `.hwp шаардсаар байгаа албан газар, маягтад зориулав. Filee Word баримтыг өөрийн бичигчээр HWPX болгож, түүнийг rhwp-ээр HWP болгоно, хоёулаа дотоод тул хөрвүүлэхэд Hancom Office хэрэггүй.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Word баримтын хуудас бүр JPG болно (Filee эхлээд баримтыг PDF болгон байрлуулна); хуудсыг онлайнаар нийтлэх эсвэл хурдан урьдчилан харах зураг илгээхэд тохиромжтой. Word хэрэггүй.`],

  // Conversion guides: spreadsheets
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Харагдах хуудас бүр өөрийн хэсэг болж, тооны формат, фонт, дүүргэлт, хүрээ, нэгтгэсэн нүдийг Excel-ийн харуулдаг шиг хадгална. Өргөн хуудсыг Excel-ийн "Бүх баганыг нэг хуудсанд багтаах" шиг хуудасны өргөнд багтаах ба царцаасан толгой мөр хуудас бүрт давтагдана.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV нэг л хүснэгт агуулдаг тул Filee хуудас бүрт нэг CSV бичнэ. Нүднүүдийг утга болгон экспортлох тул өгөгдлийн сан, скрипт, импортын маягтад бэлэн.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `XLSX ажлын ном нь CSV хадгалж чаддаггүй хэлбэржүүлэлт, томьёо, нэмэлт хуудсыг агуулж чадна. Бүх CSV экспортоо сонгоод нэг дор тавибал Excel-ийн импортын цонхгүйгээр файл бүрт нэг ажлын ном гарна.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Хуучин Excel 97–2003 ажлын номыг Excel эсвэл LibreOffice-гүйгээр шинэчлээрэй: хөрвүүлэлт дотоод. XLSX файл ихэвчлэн жижиг, макро агуулж чаддаггүй бөгөөд одоогийн бүх хүснэгтийн програмд нээгдэнэ.`],

  // Conversion guides: presentations
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Слайд бүр слайдын хэмжээтэй нэг PDF хуудас болж, текст, дүрс, зураг, хүснэгт, мастер загвартайгаа байна. Слайдыг тараах эсвэл PowerPoint файл хүлээн авдаггүй газар байршуулахад тохиромжтой. Хөдөлгөөнт эффект ба илтгэгчийн тэмдэглэл PDF-д орохгүй.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Хуучин PowerPoint 97–2003 слайд хэн ч нээж, хэвлэж, байршуулж чадах PDF болно. Keynote (.key), ODP, WPS (DPS) илтгэлийг ч адилхан хөрвүүлнэ.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Слайд бүр JPG болж, сошиал нийтлэл, жижиг зураг, чатын мессеж эсвэл видео засварлагчид бэлэн болно. Слайдад жижиг текст их байвал оронд нь PNG-г сонгоорой.`],

  // Conversion guides: text
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Гарчиг, жагсаалт (ажлын жагсаалт ч), хүснэгт, код, ишлэл, холбоос, зураг, зүүлт, математикийг Pandoc, LaTeX эсвэл хөтөчгүйгээр A4 хуудсанд байрлуулна. Markdown уншдаггүй хүмүүстэй тэмдэглэл, README файл хуваалцах хурдан арга.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Дотоод, Pandoc хэрэггүй. Гарчиг, жагсаалт, хүснэгт, холбоос, зүүлт шилждэг тул баримтыг Word-д үргэлжлүүлэн засварлаж, загварыг нь өөрчилж болно.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Энгийн текст мөр бүрт нэг догол мөртэй цэвэр A4 PDF болно. Filee UTF-8, UTF-16 болон хуучин солонгос (CP949) текст файлыг танидаг тул хуучин лог, тэмдэглэл ойлгомжгүй тэмдэгт болж хувирахгүй.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Вэб хуудас эсвэл HTML тайланг хаана ч адилхан харагдах, архивлах эсвэл хэвлэх боломжтой PDF болгон хадгалаарай. Filee таны PC дээр хадгалсан .html файлыг хөрвүүлэх ба хэд хэдийг нь нэг PDF болгон нэгтгэж болно.`],

  // Conversion guides: e-books
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `PDF хуудасны тогтмол бүтцийг хадгалдаг тул цахим номыг хэвлэх, PC дээр унших эсвэл EPUB уншигчгүй төхөөрөмж рүү илгээхэд тохиромжтой.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Хуучин Kindle/Mobipocket номын сангаа EPUB руу шилжүүлбэл Apple Books, Google Play Books, Kobo болон ихэнх унших програмд нээгдэнэ. Энэ чиглэл дотоод тул Calibre хэрэггүй.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `MOBI ба AZW3 файлыг цахим номын хэрэгсэл Calibre бичнэ. Одоогийн Kindle EPUB-ийг Send to Kindle-ээр бас хүлээн авдаг тул MOBI голчлон хуучин Kindle төхөөрөмж, програмд хэрэгтэй.`],

  // Conversion guides: video
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Лекц, концерт, ярилцлагын дууг хаана ч тоглогдох MP3 болгон хадгалаарай: машинд, хуучин тоглуулагчид эсвэл текст болгох хэрэгсэлд.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `iPhone ба Mac-ийн видео MOV файл байдаг. MP4 болохоор Android утас, ухаалаг зурагт, хуучин Windows програм болон MOV хүлээн авдаггүй байршуулах маягт дээр тоглогдоно. Видео ба дуу ихэвчлэн MP4-т байгаагаараа багтдаг тул Filee зөвхөн савыг солино: чанар алдагдахгүй, HDR хадгалагдаж, хэдхэн секундэд дуусна. MP4 720p урьдчилсан тохиргоо 4K бичлэгийг хуваалцахад зориулж жижигрүүлнэ.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Жишээ нь OBS-ийн MKV бичлэгийг видео засварлагч ихэвчлэн импортолж чаддаггүй, зурагт тоглуулдаггүй бол MP4-ийг бараг хаа сайгүй хүлээн авдаг. Хөрвүүлэлт таны компьютер дээр явагдах тул урт бичлэгийг байршуулах шаардлагагүй.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Дэлгэцийн бичлэг болон хөтчөөс хадгалсан видео ихэвчлэн WebM байдаг бөгөөд олон видео засварлагч, хуучин тоглуулагч, мессежийн програм муу боловсруулдаг. MP4 бараг хаа сайгүй тоглогдох ба олон бичлэгийг нэг дор хөрвүүлнэ.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Богино бичлэгийг чат, баримтжуулалт эсвэл алдааны тайланд зориулж хөдөлгөөнт GIF болгоорой. Богино байлгаарай: GIF кадр бүрийг 256 өнгөт зураг болгон хадгалдаг тул урт эсвэл өндөр нягтралтай видео маш том файл болно.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `JPG дээр тавьсан видеоноос нэг хөдөлгөөнгүй зураг гарна. Жижиг зураг сонгох эсвэл бичлэгийг кадр кадраар үзэхийн тулд Кадруудыг салгах (JPG) урьдчилсан тохиргоог ашиглаарай: зургууд видеоны хажуудах хавтсанд бүх кадраар эсвэл N дэх бүрээр очно. 100 000-аас олон зураг гаргах эсвэл дискийг дүүргэх видеог эхлэхээс өмнө татгалзана.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Хуучин видео камер, камерын AVI файл том бөгөөд утас, зурагтын тоглуулахаа больсон кодек ихэвчлэн ашигладаг. Орчин үеийн шахалттай MP4 ихэвчлэн хамаагүй жижиг бөгөөд хаа сайгүй тоглогдоно.`],

  // Conversion guides: audio
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `WAV бичлэг минут тутамд 10 MB орчим эзэлдэг; MP3 болохоор үүний багахан хэсэг шаардагдах ба бүх төхөөрөмж дээр тоглогдсоор байна.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Алдагдалгүй FLAC сангаа гэртээ үлдээж, MP3 хуулбарыг утас, машины USB эсвэл FLAC тоглуулдаггүй хуучин тоглуулагчид хийгээрэй. Бүтэн цомгийг нэг дор хөрвүүлнэ.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `iPhone-ийн дуу хоолойн тэмдэглэл, DRM-гүй iTunes татаж авалт болон олон дуу хураагуур M4A гаргадаг. MP3-ийг бүх тоглуулагч, машины аудио, байршуулах маягт хүлээн авдаг.`],

  // Conversion guides: archives
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Зөвхөн ZIP хүлээн авдаг хүмүүс, байршуулах маягт, системд зориулж RAR архивыг ZIP болгон дахин багцлаарай. RAR унших, ZIP бичихэд WinRAR хэрэггүй.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z ихэвчлэн илүү сайн шахдаг ч ZIP нэмэлт програмгүйгээр ямар ч компьютер, утсан дээр нээгдэнэ. 7-Zip-гүй хүнд архив илгээхдээ хөрвүүлээрэй.`],

  // Conversion guides: CAD
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `AutoCAD-гүй үйлчлүүлэгч, барилгын баг, хэвлэх үйлдвэрт зураг илгээгээрэй: PDF ямар ч PC эсвэл утсан дээр нээгдэнэ. Хэд хэдэн зургийг нэг PDF болгон нэгтгэж болно.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `CAD програм, лазер огтлолын ажил эсвэл дизайны солилцооноос ирсэн DXF файл хэн ч нээж, хэвлэж чадах PDF болно. Жишээ нь вэб урьдчилсан харагдацад SVG, PNG бас боломжтой.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF бол лазер огтлогч, CNC програм болон ихэнх CAD програмын уншдаг солилцооны формат. DWG-г DXF руу хөрвүүлбэл AutoCAD-ийн зургийг тэдгээр хэрэгсэлд нээж болох ба DXF-ийг буцааж DWG болгох нь бас ажиллана.`],

  // Conversion guides: fonts
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Вэб сайтдаа фонтоо өөрөө байршуулаарай: WOFF2 бол бүх орчин үеийн хөтчийн дэмждэг шахсан вэб фонтын формат бөгөөд ихэвчлэн WOFF-оос 30 % орчим жижиг. Фонтын лиценз вэбэд суулгахыг зөвшөөрч байгаа эсэхийг шалгаарай.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Зарим хуучин програм, огтлох ба хатгамлын машин, тоглоомын хөдөлгүүр зөвхөн TrueType фонт хүлээн авдаг. OTF фонтын бүхэл гэр бүлийг фонт засварлагчгүйгээр нэг дор TTF руу хөрвүүлээрэй.`],

  // Conversion guides: tracing and SVG → CAD
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Лого, гарын үсэг, скан хийсэн зурагт Зураасан зургийг SVG болгох урьдчилсан тохиргоог ашиглаарай: бэх нь тунгалаг дэвсгэр дээрх нэг хар дүрс болно. SVG болгож мөшгөх нь дүрс тэмдэг, чимэглэлд 64 хүртэл өнгө хадгална. Гэрэл зураг хавтгай толбо болж гардаг тул мөшгөх нь зурагт хамгийн тохиромжтой.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Логоны эсвэл скан хийсэн ноорог зургийн JPG ямар ч хэмжээнд тод хэвээр байх SVG болж, огтлох плоттер, вэб сайт эсвэл хэвлэх үйлдвэрт бэлэн болно. JPG-ийн шуугиан жижиг толбо болж хувирдаг тул үр дүн хэт ачаалалтай харагдвал урьдчилсан тохиргоон дахь Нарийвчлалын тохиргоог бууруулаарай.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Лазер огтлогч, CNC програм, CAD програм DXF уншдаг. Filee SVG-ийн контурыг миллиметрээр бичдэг тул 100 мм өргөн дүрс 100 мм хэвээр үлдэнэ. Муруй нь нарийн хугархай шугам болно. Дүүргэлт, зураг, шүүлтүүрийг орхино.`],

  // Conversion guides: e-mail
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Outlook-оос чирж гаргасан цахим шуудан зөвхөн Outlook нээдэг MSG файл болдог. PDF болохоор илгээгч, хүлээн авагч, огноо, гарчиг, мессежээ хадгалж, хаана ч нээгдэнэ. Outlook хэрэггүй.`],

  // Conversion guides: data
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML-ийг гараар унших, засварлахад илүү хялбар тул тохиргооны файлууд үүнийг ашигладаг. Түлхүүрүүд дарааллаа хадгалах ба тоо эсвэл true/false болж уншигдах текстийг хашилтад авна.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Тохиргооны файлыг зөвхөн JSON уншдаг API, скрипт эсвэл хэрэгсэлд зориулж JSON болгоорой. Зангуу ба өөр нэрсийг задлах ба хэд хэдэн баримттай файл нэг массив болно. JSON-д тайлбар байдаггүй тул тайлбарыг орхино.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Бичлэгийн JSON жагсаалт Excel-д нээж болох хүснэгт болно: бичлэг бүрт нэг мөр, түлхүүр бүрт нэг багана. {"users": […]} мэт бүрхүүлийн дотор нь харна. Хүснэгт биш өгөгдөл эвдэрсэн файл гаргахын оронд мессежээр зогсоно.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Хаягийн дэвтрээ Excel эсвэл шуудан илгээх хэрэгсэлд оруулаарай: харилцагч бүрт нэр, байгууллага, имэйл, утас, хаяг, төрсөн өдөр бүхий нэг мөр. CP949-тэй хуучин солонгос утасны харилцагчдыг зөв уншина.`],

  // Conversion guides: subtitles
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Вэб тоглуулагч, онлайн сургалтын платформ WebVTT шаарддаг. Хугацаа, мөр шилжилт, налуу бичиг шилжих ба хөдөлгүүр хэрэггүй.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Олон тоглуулагч, зурагт, засварлагч SMI уншдаггүй бөгөөд хуучин солонгос SMI файл ихэвчлэн эвдэрсэн текст харагддаг. Filee CP949-ийг танин, хамгийн олон мөртэй хэлийг сонгож, цэвэр UTF-8 SRT хадгална.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Зурагт, утас эсвэл видео сайт загварлаг ASS хадмалаас татгалзвал энгийн SRT ажиллана. Тод, налуу, доогуур зураас, өнгө хадгалагдана; байрлал, фонт, эффект орхигдоно.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Киноны хадмалыг засварлах эсвэл орчуулахын тулд гаргаж аваарай. Эхний текст хадмалын замыг SRT болгон хадгална; зураг дээр суурилсан хадмалыг (DVD, Blu-ray) текст болгох боломжгүй. Үнэгүй FFmpeg хөдөлгүүр хэрэгтэй.`],

  // Conversion guides: 3D models
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Хэвлэх файлыг OBJ илүүд үздэг 3D програмд нээгээрэй. STL нэгжгүй тул Filee үүнийг миллиметрээр уншиж, OBJ-ийг ч миллиметрээр, ихэнх 3D програмын адил Y-ийг дээш чиглүүлэн бичнэ.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `3D принтерийн slicer STL хүлээн авдаг. Ямар ч хэлбэрийн талыг гурвалжин болгон хувааж, Y-дээш нь Z-дээш болдог тул босоо загвар хэвлэх тавцан дээр зогсоно. STL зөвхөн хэлбэрийг хадгалах тул өнгө ба бүтэц OBJ-д үлдэнэ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Вэб эсвэл тоглоомын хөдөлгүүрийн загварыг OBJ уншдаг програм руу оруулаарай. .mtl файл ба бүтцүүдийг .obj-ийн хажууд бичдэг тул тэдгээрийг хамт хадгалаарай.`],

  // FAQ
  [`Is Filee really free?`, `Filee үнэхээр үнэгүй юу?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Тийм. Filee бол MIT лицензтэй үнэгүй, нээлттэй эхийн програм: зар сурталчилгаа, усан тэмдэг, бүртгэл, туршилтын хугацаа, өөрийн гэсэн файлын тоо, хэмжээний хязгаар байхгүй.`],
  [`Does it work offline? Are my files uploaded?`, `Офлайнаар ажилладаг уу? Миний файл байршуулагддаг уу?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Бүх хөрвүүлэлт таны PC дээр явагдах ба файл хэзээ ч байршуулагддаггүй. Интернэтийг зөвхөн нэмэлт хөдөлгүүр татах эсвэл шинэчлэл шалгахад ашигладаг тул нууц баримт, гэрэл зураг, бичлэг таны компьютер дээр үлдэнэ.`],
  [`Which file formats does Filee support?`, `Filee ямар файлын форматыг дэмждэг вэ?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee {categoryCount} ангилалд {formatTotal} файлын формат уншдаг: {categoryList}. Тэдгээрийн {builtinTotal} нь суулгасны дараа шууд ажиллах ба бусад нь үнэгүй нэмэлт хөдөлгүүр ашиглана. Форматын каталог бүх формат болон тэдгээр юу руу хөрвөхийг жагсаана.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Microsoft Office, Hancom Office эсвэл LibreOffice хэрэгтэй юу?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF. Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Үгүй. Word, Excel, PowerPoint файл (DOCX, XLSX, XLS, CSV, PPTX) болон солонгос HWP/HWPX баримтыг Filee-д суулгасан хөдөлгүүрүүд хөрвүүлнэ. Filee нь Office эсвэл Hancom Office суулгасан байсан ч ашигладаггүй; LibreOffice бол DOC, PPT, ODT, RTF зэрэг хуучин форматад зориулсан програм дотроос татдаг нэмэлт зүйл. Хэлбэржүүлэлт шаардлагатай текст (араб, еврей, энэтхэг бичиг, тай болон бусад) нь үл хамаарах зүйл: ийм тексттэй DOCX, TXT, Markdown, HTML, XLSX, PPTX, HWPX файл нэмэлт LibreOffice хөдөлгүүрээр PDF ба зураг руу хөрвөнө. LibreOffice байхгүй бол эвдэрсэн PDF гаргахын оронд тухайн бичгийн нэрийг дурдсан мессежээр бүтэлгүйтнэ.`],
  [`What are the optional engines?`, `Нэмэлт хөдөлгүүр гэж юу вэ?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Том хөдөлгүүрүүд суулгагчид ордоггүй. Суулгагчийн хөдөлгүүрийн хуудсанд сонгох, эсвэл хэрэгтэй үедээ Filee дотроос татаж аваарай: {engineDetails}. Тэдгээр нь Filee-ийн өөрийн хавтсанд хадгалагдах ба хүссэн үедээ устгаж болох бөгөөд програм тэдгээрийн хувилбар, татах хурд, үлдсэн хугацааг харуулна. FFmpeg, calibre, Pandoc, Ghostscript эсвэл LibreOffice таны PC дээр (PATH дээр, Scoop-ийг оролцуулан, эсвэл Program Files-д) аль хэдийн байгаа бол Filee түүнийг ашиглаж, татахыг алгасах ба тухайн хуулбар туршсан хувилбараас хуучин бол хэлнэ. Тохиргоо → Хөдөлгүүрүүд → Миний хувилбарыг ашиглах хэсгээс тодорхой нэгийг сонгоно.`],
  [`Does installing Filee need administrator rights?`, `Filee суулгахад администраторын эрх хэрэгтэй юу?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Зөвхөн нэг удаа, суулгах үед. Суулгагч Filee-г бүх хэрэглэгчид зориулж Program Files-д байрлуулах ба Windows 11 дээр File Explorer-ийн цэсний дээд хэсэгт “Filee-ээр хөрвүүлэх”-ийг нэмнэ. Үүний дараа Filee өөрөө таны ердийн хэрэглэгчээр ажиллана. Чимээгүй суулгахын тулд суулгагчийг /VERYSILENT /SUPPRESSMSGBOXES-тэй ажиллуулна. Програм суулгах боломжгүй бол зөөврийн ZIP-ийг ашиглаарай: хаана ч задлаад Filee.exe-г ажиллуулна.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Windows 10 дээр Filee эхлэхгүй байна: цонх ч, алдаа ч гарахгүй. Яах вэ?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Энэ нь удаан хугацаанд шинэчлэгдээгүй Windows 10 дээр, процессор нь Тоног төхөөрөмжөөр хангагдсан стекийн хамгаалалтыг (CET) дэмждэг PC дээр тохиолддог. Windows энэ хамгаалалтыг асаадаг ч .NET-д хэрэгтэй хэсэг дутуу байдаг тул Filee болон түүний суулгагч цонх ч, мессеж ч үгүй шууд зогсдог. Боломжтой Windows шинэчлэлүүдийг (хамгийн сүүлийн хуримтлагдсан шинэчлэл) суулгавал засагдана. Шинэчлэх боломжгүй бол зөвхөн Filee-д хамгаалалтыг унтраах нь ихэвчлэн ажилладаг: PowerShell-ийг администратороор нээж Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack-ийг ажиллуулаад filee-cli.exe болон суулгагчийн файлын нэрд мөн адил хийнэ (эсвэл зөөврийн ZIP-ийг ашиглана). Буцаахын тулд Windows Security → App & browser control → Exploit protection settings → Program settings хэсгээс тэдгээр бичилтийг устгана.`],
  [`Can I convert many files at once?`, `Олон файлыг нэг дор хөрвүүлж болох уу?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Тийм. Хүссэн хэмжээгээрээ файл сонгоод нэг удаа тавиарай: Filee тэдгээрийг зэрэгцээ хөрвүүлж, бүтэлгүйтсэн файл бусдыг хэзээ ч зогсоохгүй бөгөөд урьдчилсан тохиргоо бүгдийг нэг PDF болгон нэгтгэх эсвэл нэг ZIP болгон багцалж чадна.`],
  [`Can I convert from the Windows 11 right-click menu?`, `Windows 11-ийн баруун товчны цэснээс хөрвүүлж болох уу?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Тийм. File Explorer-т файлууд дээр баруун товшоод "Filee-ээр хөрвүүлэх"-ийг сонгоно. Windows 11 дээр үүнийг "Show more options"-гүйгээр дээд түвшний цэсэнд ч байрлуулж болно: Тохиргоо → Ерөнхий хэсэгт "Үндсэн цэсэнд нэмэх"-ийг нэг удаа дарж, администраторын хүсэлтийг зөвшөөрнө. Send To, гарын товчлол, үндсэн цонхны чирж тавих хэсэг ч ажиллана.`],
  [`Can Filee convert from the command line or automatically?`,
    `Filee командын мөрөөс эсвэл автоматаар хөрвүүлж чадах уу?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Тийм. Суулгагч filee командыг PATH-д нэмж чадна: filee convert *.heic --to jpg нь файл, тэмдэгт загвар, хавтсыг таны урьдчилсан тохиргоогоор хөрвүүлж, скриптэд JSON хэвлэн, гарах код буцаана. Хянах хавтаснууд хавтсанд орж ирсэн файлыг автоматаар хөрвүүлж, эх файлыг өөр тийш зөөж чадна. Тэдгээрийг програмын Хянах хавтаснууд хуудсанд эсвэл терминалд filee watch-оор тохируулна.`],
  [`How do I convert a file, for example HEIC to JPG?`, `Файлыг, жишээ нь HEIC-ийг JPG руу яаж хөрвүүлэх вэ?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `File Explorer-т файлуудаа сонгоод Ctrl (эсвэл таны сонгосон товч)-ыг дарсан чигээр чирнэ. Курсорын дэргэд форматын цагираг нээгдэнэ: файлуудыг JPG дээр тавихад шинэ файлууд эхийнхээ хажууд гарч ирнэ. Хамгийн түгээмэл хөрвүүлэлтүүдэд алхам алхмаар заавар бий.`],
  [`Why use Filee instead of an online converter?`, `Онлайн хөрвүүлэгчийн оронд яагаад Filee ашиглах вэ?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Онлайн хөрвүүлэгч таны файлыг бусдын сервер рүү байршуулж, файлын хэмжээ, тоог ихэвчлэн хязгаарлаж, хурдан холболтоос хамаардаг. Filee таны PC дээр хөрвүүлнэ: хувийн файл хувийн хэвээр, том видео болон хэдэн зуун файл асуудалгүй бөгөөд интернэтгүй, үнэгүй, зар сурталчилгаагүй ажиллана.`],
  [`Which operating systems are supported?`, `Ямар үйлдлийн систем дэмжигддэг вэ?`],
  [`Windows 10 and 11 (x64 and ARM64) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 ба 11 (x64 ба ARM64), Linux (x64 ба ARM64, Ubuntu 22.04 эсвэл түүнээс хойшхи) бүрэн хувилбартай. Linux дээр чирэх дохио X11 сесс шаарддаг; Wayland-тай KDE Plasma дээр туршилтын шатанд, бусад Wayland ширээн дээр чирж тавих хэсэг болон файлын менежерийн баруун товчны цэс ажиллана. macOS 13 эсвэл түүнээс хойшхи (Apple silicon ба Intel) урьдчилсан хувилбар: програм хараахан нотариатаар баталгаажаагүй тул macOS Нууцлал ба Аюулгүй байдал хэсэгт нэг удаа зөвшөөрөхийг хүснэ. Татах хэсгээс системээ сонгоорой.`],
]);
